// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * M-F2: the ValueExpr → FragmentIR translator serves filter conditions the specialized filter compilers decline (NOT
 * combinations, arithmetic comparisons) as primitive fragments with the generic predicate demoted to the ESCAPE
 * fallback. Differential against the generic arm; engagement pinned through the translator counter.
 */
public class LmdbNativeFragmentTranslatorTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			IRI val = vf.createIRI(EX, "val");
			conn.add(vf.createIRI(EX, "s1"), val, vf.createLiteral(1));
			conn.add(vf.createIRI(EX, "s2"), val, vf.createLiteral(2));
			conn.add(vf.createIRI(EX, "s3"), val, vf.createLiteral(3));
			conn.add(vf.createIRI(EX, "s4"), val, vf.createLiteral("abc"));
			IRI a = vf.createIRI(EX, "a");
			IRI b = vf.createIRI(EX, "b");
			// s5: numerically equal but distinct terms (xsd:int vs xsd:long); s6: the same term twice
			conn.add(vf.createIRI(EX, "s5"), a, vf.createLiteral(1));
			conn.add(vf.createIRI(EX, "s5"), b, vf.createLiteral(1L));
			conn.add(vf.createIRI(EX, "s6"), a, vf.createLiteral(2));
			conn.add(vf.createIRI(EX, "s6"), b, vf.createLiteral(2));
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	private List<BindingSet> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
		}
	}

	private List<BindingSet> genericRows(String query) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return rows(query);
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private void assertSameAsGenericAndTranslated(String query) {
		List<BindingSet> generic = genericRows(query);
		long translatedBefore = LmdbNativeFragmentTranslator.TRANSLATED.get();
		assertThat(rows(query)).as("native vs generic for:\n" + query)
				.containsExactlyInAnyOrderElementsOf(generic);
		assertThat(LmdbNativeFragmentTranslator.TRANSLATED.get() - translatedBefore)
				.as("the condition must be served by the fragment translator (previously the generic predicate):\n"
						+ query)
				.isGreaterThanOrEqualTo(1);
	}

	/** NOT over a comparison conjunction: three-valued semantics incl. the error row ("abc" comparisons error). */
	@Test
	public void notCombinationFilterIsTranslated() {
		assertSameAsGenericAndTranslated(
				"SELECT ?s WHERE { ?s <" + EX + "val> ?v . FILTER(!(?v > 1 && ?v < 3)) }");
	}

	/** Arithmetic comparison: inline-integer fast path, error row escapes/errors like the generic arm. */
	@Test
	public void arithmeticComparisonFilterIsTranslated() {
		assertSameAsGenericAndTranslated(
				"SELECT ?s WHERE { ?s <" + EX + "val> ?v . FILTER(?v + 1 < 3) }");
	}

	/** NOT of BOUND under OPTIONAL — the classic negation-as-failure shape. */
	@Test
	public void notBoundFilterIsTranslated() {
		assertSameAsGenericAndTranslated(
				"SELECT ?s WHERE { ?s <" + EX + "val> ?v . OPTIONAL { ?s <" + EX + "other> ?w } "
						+ "FILTER(!BOUND(?w)) }");
	}

	/**
	 * sameTerm is term identity, not numeric equality: equal-valued inline integers of different XSD datatypes
	 * ({@code "1"^^xsd:int} vs {@code "1"^^xsd:long}) are different terms and must be rejected. The disjunction keeps
	 * the sameTerm out of SameTermFilterOptimizer's reach so the filter actually evaluates it.
	 */
	@Test
	public void sameTermDistinguishesIntegerDatatypesAcrossVariables() {
		assertSameAsGenericAndTranslated(
				"SELECT ?s WHERE { ?s <" + EX + "a> ?x . ?s <" + EX + "b> ?y . "
						+ "FILTER(sameTerm(?x, ?y) || ?x > 10) }");
	}

	/**
	 * The variable-vs-constant shape of the same trap: sameTerm against an equal-valued constant of another datatype.
	 */
	@Test
	public void sameTermDistinguishesIntegerDatatypesAgainstConstant() {
		assertSameAsGenericAndTranslated(
				"SELECT ?s WHERE { ?s <" + EX + "a> ?x . "
						+ "FILTER(sameTerm(?x, \"1\"^^<http://www.w3.org/2001/XMLSchema#long>) || ?x > 10) }");
	}

	/** Conditions outside batch 1 (REGEX) keep today's generic route — differential only. */
	@Test
	public void regexKeepsTheGenericRoute() {
		String query = "SELECT ?s WHERE { ?s <" + EX + "val> ?v . FILTER(REGEX(STR(?v), \"^a\")) }";
		assertThat(rows(query)).containsExactlyInAnyOrderElementsOf(genericRows(query));
	}
}
